#include <bits/stdc++.h>
using namespace std;
int main(){
  int n,m;
  cin>>n>>m;
  vector<int> a(m);
  for(int i=0;i<m;i++){
    cin>>a[i];
    a[i]--;
  }
  vector<int> b(n+1);
  for(int i=0;i<m;i++) b[a[i]+1]++;
  for(int i=1;i<=n;i++) b[i]+=b[i-1];
  for(int i=0;i<n;i++){
    int ok=n,ng=i-1;
    while(abs(ok-ng)>1){
      int mid=(ok+ng)/2;
      if(b[mid+1]-b[i]>=1) ok=mid;
      else ng=mid;
    }
    cout<<ok-i<<endl;
  }
}

