#include <bits/stdc++.h>
using namespace std;
int main(){
  int n,m;
  cin>>n>>m;
  vector<int> a(m);
  for(int i=0;i<m;i++){
    cin>>a[i];
    a[i]--;
  }
  vector<int> b(n);
  for(int i=0;i<m;i++){
    b[a[i]]=1;
  }
  vector<int> ans(n);
  for(int i=n-1;i>=0;i--){
    if(b[i]){
      ans[i]=0;
    }
    else{
      ans[i]=ans[i+1]+1;
    }
  }
  for(int i=0;i<n;i++) cout<<ans[i]<<endl;
}
